import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function NewAnomaly() {
    const navigate = useNavigate();
    const [form, setForm] = useState({
        title: '',
        description: '',
        location: '',
        risk_level: 'medium'
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleChange = (e) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            console.log('📤 ارسال داده:', form);

            const response = await fetch('http://localhost:8000/api/anomalies/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(form)
            });

            console.log('📥 پاسخ سرور:', response.status);

            const data = await response.json();
            console.log('📦 داده پاسخ:', data);

            if (response.ok) {
                alert('✅ آنومالی با موفقیت ثبت شد!');
                navigate('/anomalies');
            } else {
                setError(data.message || 'خطا در ثبت آنومالی');
                alert('❌ خطا: ' + (data.message || 'مشخص نیست'));
            }
        } catch (error) {
            console.error('❌ خطا:', error);
            setError('خطا در اتصال به سرور');
            alert('❌ خطا در اتصال به سرور. مطمئن شوید بک‌اند در حال اجراست.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div>
            <h1>⚠️ ثبت آنومالی جدید</h1>
            
            {error && (
                <div style={{
                    backgroundColor: '#ffebee',
                    color: '#c62828',
                    padding: '10px',
                    borderRadius: '4px',
                    marginBottom: '20px'
                }}>
                    ❌ {error}
                </div>
            )}

            <form onSubmit={handleSubmit} style={{ maxWidth: '600px' }}>
                <div style={{ marginBottom: '15px' }}>
                    <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
                        عنوان *
                    </label>
                    <input
                        type="text"
                        name="title"
                        value={form.title}
                        onChange={handleChange}
                        style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '4px',
                            fontSize: '14px'
                        }}
                        required
                    />
                </div>

                <div style={{ marginBottom: '15px' }}>
                    <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
                        توضیحات *
                    </label>
                    <textarea
                        name="description"
                        value={form.description}
                        onChange={handleChange}
                        rows="4"
                        style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '4px',
                            fontSize: '14px',
                            fontFamily: 'inherit'
                        }}
                        required
                    />
                </div>

                <div style={{ marginBottom: '15px' }}>
                    <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
                        مکان *
                    </label>
                    <input
                        type="text"
                        name="location"
                        value={form.location}
                        onChange={handleChange}
                        style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '4px',
                            fontSize: '14px'
                        }}
                        required
                    />
                </div>

                <div style={{ marginBottom: '20px' }}>
                    <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
                        سطح ریسک
                    </label>
                    <select
                        name="risk_level"
                        value={form.risk_level}
                        onChange={handleChange}
                        style={{
                            width: '100%',
                            padding: '10px',
                            border: '1px solid #ddd',
                            borderRadius: '4px',
                            fontSize: '14px'
                        }}
                    >
                        <option value="low">🟢 کم</option>
                        <option value="medium">🟡 متوسط</option>
                        <option value="high">🟠 بالا</option>
                        <option value="critical">🔴 بحرانی</option>
                    </select>
                </div>

                <div style={{ display: 'flex', gap: '10px' }}>
                    <button
                        type="submit"
                        disabled={loading}
                        style={{
                            padding: '12px 24px',
                            backgroundColor: loading ? '#90a4ae' : '#1976d2',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: loading ? 'not-allowed' : 'pointer',
                            fontSize: '16px'
                        }}
                    >
                        {loading ? '⏳ در حال ثبت...' : '📝 ثبت آنومالی'}
                    </button>
                    <button
                        type="button"
                        onClick={() => navigate('/anomalies')}
                        style={{
                            padding: '12px 24px',
                            backgroundColor: '#666',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer',
                            fontSize: '16px'
                        }}
                    >
                        ❌ انصراف
                    </button>
                </div>
            </form>
        </div>
    );
}

export default NewAnomaly;
